export default async function f({ body, result }, ctx) {
  const id = String(body.submissionId || "");
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(id) || !body.name || !body.email || !body.enquiry)
    throw Error("Invalid request");
  const key = "appointment:" + id;
  const old = await ctx.state.get(key);
  if (old) {
    if (
      old.person.name !== body.name ||
      old.person.email !== body.email ||
      old.person.enquiry !== body.enquiry
    )
      throw Error("Submission changed");
    return { body: { relevant: old.relevant } };
  }
  await ctx.state.set(key, {
    relevant: result.relevant,
    person: { name: body.name, email: body.email, enquiry: body.enquiry },
    done: {},
    pending: null,
  });
  return { body: { relevant: result.relevant } };
}

