export default async function prepare({ body, calendarId, acknowledge, resolution }, ctx) {
  const id = String(body.submissionId || "");
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(id)) throw Error("Invalid submission ID");
  const key = "appointment:" + id;
  let s = await ctx.state.get(key);
  if (body.stage === "submit") {
    if (!s?.relevant) throw Error("No accepted classification");
    if (
      body.accepted !== true ||
      typeof body.dateTime !== "string" ||
      !Number.isFinite(Date.parse(body.dateTime))
    )
      throw Error("Terms and appointment time required");
    if (!s.request) {
      s.request = { ...s.person, dateTime: body.dateTime, summary: String(body.summary || "") };
      await ctx.state.set(key, s);
    } else if (s.request.dateTime !== body.dateTime) throw Error("Submission changed");
  } else if (body.stage === "decision") {
    if (!s?.request || !["approved", "rejected"].includes(body.decision))
      throw Error("Missing request or decision");
    if (s.decision && s.decision !== body.decision) throw Error("Decision already recorded");
    s.decision = body.decision;
    if (body.summary) s.request.summary = String(body.summary);
    await ctx.state.set(key, s);
  } else throw Error("Invalid stage");
  const phase = body.stage === "submit" ? "receipt" : s.decision,
    operationKey = key + ":" + phase;
  if (s.pending) {
    if (acknowledge !== s.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + s.pending);
    if (resolution === "confirmed") s.done[s.pending] = true;
    s.pending = null;
    await ctx.state.set(key, s);
  }
  const write = !s.done[operationKey];
  if (write) {
    s.pending = operationKey;
    await ctx.state.set(key, s);
  }
  const p = s.request,
    start = new Date(p.dateTime),
    end = new Date(start.getTime() + 1800000).toISOString(),
    to = p.email,
    subject =
      phase === "receipt"
        ? "Appointment request received"
        : phase === "rejected"
          ? "Appointment request declined"
          : "Appointment confirmed",
    message =
      phase === "receipt"
        ? `Dear ${p.name},\n\nWe received your appointment request for ${p.dateTime}. We will review it and get back to you.\n\n${p.enquiry}`
        : `Dear ${p.name},\n\nWe cannot schedule your requested appointment at ${p.dateTime}.`,
    event = {
      summary: "Appointment - " + p.name,
      start: { dateTime: p.dateTime },
      end: { dateTime: end },
      attendees: [{ email: p.email }],
      description: p.summary + "\n\nOriginal message:\n" + p.enquiry,
      conferenceData: {
        createRequest: { requestId: id, conferenceSolutionKey: { type: "hangoutsMeet" } },
      },
    };
  return {
    key,
    operationKey,
    phase,
    write,
    to,
    subject,
    message,
    event,
    calendarId,
    submissionId: id,
  };
}

