export default async function confirm({ key, operationKey, receipt, eventId }, ctx) {
  if (!receipt && !eventId) throw Error("Unknown external write");
  const s = await ctx.state.get(key);
  if (!s || s.pending !== operationKey) throw Error("Missing pending operation");
  s.done[operationKey] = true;
  s.pending = null;
  await ctx.state.set(key, s);
  return { body: { ok: true } };
}

